mapper.select:
select organization_id as organizationId, stat_date as statDate, owner_user_id as ownerUserId, owner_user_name as ownerUserName, owner_dept_id as ownerDeptId, owner_dept_name as ownerDeptName, inbound_customer_count as inboundCustomerCount, contacted_customer_count as contactedCustomerCount, dial_count as dialCount, connected_count as connectedCount, call_duration_sec as callDurationSec, call_over_1min_count as callOver1minCount, call_over_3min_count as callOver3minCount, new_wechat_friend_count as newWechatFriendCount, visit_customer_count as visitCustomerCount from report_employee_stat_day where stat_date between #{startDate} and #{endDate} and organization_id = #{orgId}
and owner_user_id in
#{ownerUserId}

select date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d') as statDate, e.customer_id as customerId, max(e.customer_source) as customerSource, e.owner_user_id as operatorUserId, 1 as inboundCustomerFlag, 0 as contactedCustomerFlag, 0 as newWechatFriendFlag, 0 as visitCustomerFlag, 0 as dialCount, 0 as connectedCount, 0 as callOver1minCount, 0 as callOver3minCount, 0 as callDurationSec from report_employee_stat_event e where e.metric_type = 'INBOUND' and e.event_time between #{startTime} and #{endTime} and e.organization_id = #{orgId}
and e.owner_user_id in
#{ownerUserId}
group by date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d'), e.customer_id, e.owner_user_id

select date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d') as statDate, e.customer_id as customerId, max(e.customer_source) as customerSource, e.owner_user_id as operatorUserId, 0 as inboundCustomerFlag, 1 as contactedCustomerFlag, 0 as newWechatFriendFlag, 0 as visitCustomerFlag, 0 as dialCount, 0 as connectedCount, 0 as callOver1minCount, 0 as callOver3minCount, 0 as callDurationSec from report_employee_stat_event e where e.metric_type = 'CONTACT' and e.event_time between #{startTime} and #{endTime} and e.organization_id = #{orgId}
and e.owner_user_id in
#{ownerUserId}
group by date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d'), e.customer_id, e.owner_user_id

select date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d') as statDate, e.customer_id as customerId, max(e.customer_source) as customerSource, e.owner_user_id as operatorUserId, 0 as inboundCustomerFlag, 0 as contactedCustomerFlag, 1 as newWechatFriendFlag, 0 as visitCustomerFlag, 0 as dialCount, 0 as connectedCount, 0 as callOver1minCount, 0 as callOver3minCount, 0 as callDurationSec from report_employee_stat_event e where e.metric_type = 'WECHAT_FRIEND' and ifnull(e.valid_flag, 1) = 1 and e.event_time between #{startTime} and #{endTime} and e.organization_id = #{orgId}
and e.owner_user_id in
#{ownerUserId}
group by date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d'), e.customer_id, e.owner_user_id

select date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d') as statDate, e.customer_id as customerId, max(e.customer_source) as customerSource, e.owner_user_id as operatorUserId, 0 as inboundCustomerFlag, 0 as contactedCustomerFlag, 0 as newWechatFriendFlag, 1 as visitCustomerFlag, 0 as dialCount, 0 as connectedCount, 0 as callOver1minCount, 0 as callOver3minCount, 0 as callDurationSec from report_employee_stat_event e where e.metric_type = 'VISIT_CUSTOMER' and ifnull(e.valid_flag, 1) = 1 and e.event_time between #{startTime} and #{endTime} and e.organization_id = #{orgId}
and e.owner_user_id in
#{ownerUserId}
group by date_format(from_unixtime(e.event_time / 1000), '%Y-%m-%d'), e.customer_id, e.owner_user_id

select e.customer_id as customerId,
       e.customer_name as customerName,
       e.customer_mobile as mobile,
       e.owner_user_name as ownerName,
       e.owner_dept_name as departmentName,
       e.customer_source as customerSource,
       e.event_time as eventTime
from report_employee_stat_event e
where e.metric_type = 'INBOUND'
  and e.organization_id = #{orgId}
  and e.event_time between #{request.startTime} and #{request.endTime}

      and e.owner_user_id in

          #{ownerUserId}



      and e.owner_user_id = #{request.dimensionKey}


      and e.owner_dept_id = #{request.dimensionKey}


      and ifnull(e.customer_source, '') = ''


      and ifnull(e.customer_source, '') = #{request.dimensionKey}


      and e.stat_date = #{request.dimensionKey}


      and substring(e.stat_date, 1, 7) = #{request.dimensionKey}

order by e.event_time desc, e.id desc

select e.customer_id as customerId,
       max(e.customer_name) as customerName,
       max(e.customer_mobile) as mobile,
       max(e.owner_user_name) as ownerName,
       max(e.owner_dept_name) as departmentName,
       max(e.customer_source) as customerSource,
       max(e.event_time) as eventTime
from report_employee_stat_event e
where e.metric_type = 'CONTACT'
  and e.organization_id = #{orgId}
  and e.event_time between #{request.startTime} and #{request.endTime}

      and e.owner_user_id in

          #{ownerUserId}



      and e.owner_user_id = #{request.dimensionKey}


      and e.owner_dept_id = #{request.dimensionKey}


      and ifnull(e.customer_source, '') = ''


      and ifnull(e.customer_source, '') = #{request.dimensionKey}


      and e.stat_date = #{request.dimensionKey}


      and substring(e.stat_date, 1, 7) = #{request.dimensionKey}

group by e.customer_id
order by max(e.event_time) desc, e.customer_id desc

select max(e.biz_trace_id) as auditId,
       e.customer_id as customerId,
       max(e.customer_name) as customerName,
       max(e.customer_mobile) as mobile,
       max(e.owner_user_name) as ownerName,
       max(e.owner_dept_name) as departmentName,
       max(e.customer_source) as customerSource,
       max(e.event_time) as eventTime
from report_employee_stat_event e
where e.metric_type = 'WECHAT_FRIEND'
  and ifnull(e.valid_flag, 1) = 1
  and e.organization_id = #{orgId}
  and e.event_time between #{request.startTime} and #{request.endTime}

      and e.owner_user_id in

          #{ownerUserId}



      and e.owner_user_id = #{request.dimensionKey}


      and e.owner_dept_id = #{request.dimensionKey}


      and ifnull(e.customer_source, '') = ''


      and ifnull(e.customer_source, '') = #{request.dimensionKey}


      and e.stat_date = #{request.dimensionKey}


      and substring(e.stat_date, 1, 7) = #{request.dimensionKey}

group by e.customer_id
order by max(e.event_time) desc, max(e.biz_trace_id) desc

select max(e.biz_trace_id) as auditId,
       e.customer_id as customerId,
       max(e.customer_name) as customerName,
       max(e.customer_mobile) as mobile,
       max(e.owner_user_name) as ownerName,
       max(e.owner_dept_name) as departmentName,
       max(e.customer_source) as customerSource,
       max(e.event_time) as eventTime
from report_employee_stat_event e
where e.metric_type = 'VISIT_CUSTOMER'
  and ifnull(e.valid_flag, 1) = 1
  and e.organization_id = #{orgId}
  and e.event_time between #{request.startTime} and #{request.endTime}

      and e.owner_user_id in

          #{ownerUserId}



      and e.owner_user_id = #{request.dimensionKey}


      and e.owner_dept_id = #{request.dimensionKey}


      and ifnull(e.customer_source, '') = ''


      and ifnull(e.customer_source, '') = #{request.dimensionKey}


      and e.stat_date = #{request.dimensionKey}


      and substring(e.stat_date, 1, 7) = #{request.dimensionKey}

group by e.customer_id
order by max(e.event_time) desc, max(e.biz_trace_id) desc

select cra.es_id as auditId, cra.customer_id as customerId, cra.customer as customerName, cra.customer_tel as mobile, cra.staff_name as staffName, cra.biz_ext_info as bizExtInfo, cra.begin_timestamp as eventTime, cra.begin_time as beginTime, cra.end_time as endTime, cra.duration, cra.is_connected as isConnected, cra.direction from mmba_call_record_audit cra join sys_user su on su.um = cra.um join sys_organization_user action_sou on action_sou.organization_id = #{orgId} and action_sou.user_id = su.id where cra.begin_timestamp between #{request.startTime} and #{request.endTime} and cra.direction = 0 and ifnull(cra.call_type, 0) = 1 and cra.customer_id is not null and cra.customer_id != ''
and su.id in
#{ownerUserId}
and ifnull(cra.is_connected, 0) = 1
and ifnull(cra.is_connected, 0) = 1 and ifnull(cra.duration, 0) >= 60
and ifnull(cra.is_connected, 0) = 1 and ifnull(cra.duration, 0) >= 180
and su.id = #{request.dimensionKey}
and action_sou.department_id = #{request.dimensionKey}
and date_format(from_unixtime(cra.begin_timestamp / 1000), '%Y-%m-%d') = #{request.dimensionKey}
and date_format(from_unixtime(cra.begin_timestamp / 1000), '%Y-%m') = #{request.dimensionKey}
order by cra.begin_timestamp desc, cra.es_id desc

select id, operator_user_id as operatorUserId, customer_mobile as customerMobile, event_time as eventTime from report_employee_stat_event where metric_type = 'WECHAT_FRIEND' and valid_flag = 0 and customer_mobile = #{friendPhone} and operator_user_id in
#{operatorUserId}
order by event_time desc, create_time desc limit 2

select count(1)
from report_employee_stat_event
where metric_type = 'VISIT_CUSTOMER'
  and ifnull(valid_flag, 1) = 1
  and organization_id = #{orgId}
  and customer_id = #{customerId}
